"""Search keywords & hashtags per niche: seeded, generated by Claude, and expanded over time
from the tags/topics of videos that turned out successful."""
from __future__ import annotations

import json
import re
from collections import Counter

from .. import db, llm

SEEDS = {
    "fitness": {"en": ["home workout", "abs workout", "fat loss tips", "gym mistakes", "glute exercises", "#fitnesstips", "#gymtok"],
                "he": ["אימון בבית", "תרגילי בטן", "ירידה במשקל", "#כושר", "#אימון"]},
    "realestate": {"en": ["house tour", "real estate tips", "first time home buyer", "luxury home tour", "#realestate", "#hometour"],
                   "he": ["סיור בדירה", "נדלן", "משכנתא טיפים", "השקעות נדלן", "#נדלן"]},
    "food": {"en": ["easy recipe", "high protein recipe", "5 minute meal", "air fryer recipe", "#recipe", "#foodtok"],
             "he": ["מתכון קל", "מתכון מהיר", "ארוחת ערב", "#מתכונים", "#אוכל"]},
    "business": {"en": ["small business tips", "how to make money", "marketing tips", "entrepreneur advice", "#business", "#entrepreneur"],
                 "he": ["טיפים לעסקים", "שיווק דיגיטלי", "יזמות", "#עסקים", "#יזמות"]},
}

SCHEMA = {
    "type": "object",
    "properties": {
        "keywords": {"type": "array", "items": {"type": "string"}},
        "hashtags": {"type": "array", "items": {"type": "string"}},
    },
    "required": ["keywords", "hashtags"],
    "additionalProperties": False,
}


def _add(niche: str, kw: str, origin: str) -> bool:
    kw = kw.strip()
    if not kw or len(kw) > 60:
        return False
    kind = "hashtag" if kw.startswith("#") else "keyword"
    with db.connect() as con:
        cur = con.execute("INSERT OR IGNORE INTO keywords (niche, keyword, kind, origin, added_at) VALUES (?,?,?,?,?)",
                          (niche, kw, kind, origin, db.now()))
        return cur.rowcount > 0


def ensure_seeded(niche: str, languages: list[str]) -> None:
    if db.one("SELECT 1 FROM keywords WHERE niche=?", (niche,)):
        return
    seeds = SEEDS.get(niche, {"en": [niche, f"{niche} tips", f"#{niche}"], "he": []})
    for lang in languages:
        for kw in seeds.get(lang, []):
            _add(niche, kw, "seed")
    generate_with_claude(niche, languages)


def generate_with_claude(niche: str, languages: list[str], context: str = "") -> int:
    if not llm.available():
        return 0
    existing = [r["keyword"] for r in db.rows("SELECT keyword FROM keywords WHERE niche=?", (niche,))]
    res = llm.ask_json(
        "You are a short-form video growth strategist who knows what is trending on TikTok, Reels and YouTube Shorts.",
        f"Niche: {niche}. Languages: {', '.join(languages)}.\n"
        f"Keywords we already search: {existing[:60]}\n{context}\n"
        "Propose 12 NEW search keywords and 8 NEW hashtags (with #) that surface high-performing, recent short videos "
        "in this niche. Mix evergreen and currently-trending angles, in every listed language.",
        SCHEMA, effort="low")
    if not res:
        return 0
    return sum(_add(niche, k, "claude") for k in res["keywords"] + res["hashtags"])


def expand_from_successes(niche: str, limit: int = 8) -> int:
    """Grow the keyword set from tags/topics of the best videos found so far."""
    rows = db.rows("SELECT v.tags, f.topic FROM videos v LEFT JOIN features f ON f.video_id=v.id "
                   "WHERE v.niche=? AND v.label='success' ORDER BY v.success_score DESC LIMIT 40", (niche,))
    c = Counter()
    for r in rows:
        for t in json.loads(r["tags"] or "[]"):
            t = t.strip().lower()
            if 3 <= len(t) <= 30:
                c[t if not re.match(r"^[\w֐-׿]+$", t) else "#" + t] += 1
        for t in json.loads(r["topic"] or "[]"):
            c[t] += 0.5
    added = 0
    for kw, n in c.most_common(limit * 3):
        if n >= 2 and _add(niche, kw, "expanded"):
            added += 1
        if added >= limit:
            break
    if rows:
        added += generate_with_claude(niche, ["en", "he"],
                                      context=f"Top successful video tags so far: {[k for k, _ in c.most_common(20)]}")
    return added


def pick(niche: str, n: int) -> list[dict]:
    """Rotate: least-recently-used first, favouring keywords that produced successes."""
    rows = db.rows("SELECT * FROM keywords WHERE niche=? ORDER BY (last_used IS NOT NULL), last_used, hits DESC LIMIT ?",
                   (niche, n))
    for r in rows:
        db.execute("UPDATE keywords SET uses=uses+1, last_used=? WHERE niche=? AND keyword=?", (db.now(), niche, r["keyword"]))
    return rows


def credit(niche: str, keyword: str, hits: int) -> None:
    db.execute("UPDATE keywords SET hits=hits+? WHERE niche=? AND keyword=?", (hits, niche, keyword))
